D = (-10*pi,-10*pi);

draw(B--D,red);

for (n = 1; n <= 9; ++n) {
  draw(interp(A,D,n/10)--interp(A,B,n/10),red);
	draw(interp(C,D,n/10)--interp(C,B,n/10),red);
